function missing(){return `<div class="empty panel"><h1>ไม่พบหน้าที่เลือก</h1><p>เลือกบทเรียนจากรายการอีกครั้งได้เลย</p>${link('courses','ไปที่บทเรียน')}</div>`;}
function updateNav(){const active=(currentView==='lesson'||currentView==='course')?'courses':currentView==='prep'?'exams':currentView==='note'?'notes':currentView;document.querySelector('#navigation').innerHTML=navItems.map(([key,i,label])=>`<a class="nav-link ${active===key?'active':''}" href="#${key}" ${currentView===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='courses'?`<small>${lessons.length}</small>`:''}</a>`).join('');document.querySelector('#bottom-nav').innerHTML=navItems.slice(0,5).map(([key,i,,short])=>`<a class="${active===key?'active':''}" href="#${key}" ${currentView===key?'aria-current="page"':''}>${icon(i,22)}<span>${short}</span></a>`).join('');document.querySelector('#breadcrumb').textContent=currentView==='lesson'?`${currentId.split('-')[0]} / บทเรียน`:currentView==='prep'?`${currentId} / แนวข้อสอบ`:(navItems.find(n=>n[0]===currentView)?.[2]||{course:'บทเรียนรายวิชา',about:'แหล่งเรียนรู้',settings:'ตั้งค่า'}[currentView]||'ห้องเรียน');}
