function navigate(){const raw=location.hash.startsWith('#space=')?'home':location.hash.slice(1)||'home';const [view,id]=raw.split('/');currentView=view;currentId=id||'';reviewQueue=null;if(currentView==='lesson'&&lessonById(currentId)&&studySpace.info().canEdit){state.lastLesson=currentId;save();}render();main.focus({preventScroll:true});}
function download(name,content,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportAll(){download(`ru-study-backup-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('ส่งออกไฟล์สำรองแล้ว');}
function exportPlan(){const rows=[['ภาค','รหัส','รายวิชา','หน่วยกิต','หมวด','ภาระประมาณ','วันสอบ','คาบ','ผลสอบที่บันทึกเอง','เหตุผลลำดับเรียน'],...planSummary(state).termRows.flatMap(t=>t.courses.map(c=>[t.name,c.id,c.title,3,categories[c.category],c.load,c.exam?thaiDate(c.exam):'รอประกาศ',c.slot||'',state.grades[c.id]||'',c.reason]))];const csv='﻿'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');download('ru-study-plan-all-terms.csv',csv,'text/csv;charset=utf-8');}
function toggleBlock(id){const day=today(),list=state.planDone[day]||[];state.planDone[day]=list.includes(id)?list.filter(v=>v!==id):[...list,id];const keep=Object.keys(state.planDone).sort().slice(-120);for(const k of Object.keys(state.planDone))if(!keep.includes(k))delete state.planDone[k];save();render(true);const plan=dailyPlan(state,day);if(!list.includes(id))toast(plan.done===plan.blocks.length?'ครบแผนวันนี้แล้ว เก่งมาก ✓':'ทำเสร็จอีกหนึ่งช่วง ✓');}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action.startsWith('account-')){accountAction(action,studySpace,render,toast);return;}
 if(action.startsWith('nb-')&&!studySpace.info().canEdit){toast(studySpace.info().status);return;}
 if(action.startsWith('nb-')){notebookAction(action,b.dataset,studySpace,state,render,toast);return;}
 if(action.startsWith('cal-')){if(action==='cal-export'){download('ru-study-calendar-2-2569.ics',calendarDownload(),'text/calendar;charset=utf-8');toast('ดาวน์โหลดปฏิทินทั้งเทอมตามตัวกรองแล้ว');}else if(calendarAction(action,b.dataset))render(true);return;}
 if(action==='refresh-content'){location.reload();return;}
 if(!studySpace.info().canEdit&&!['section','mode','flip','next','prev','review-course'].includes(action)){toast('กำลังเชื่อมต่อพื้นที่บันทึก คุณอ่านบทเรียนและดูตารางได้ระหว่างรอ');return;}
 if(action==='font'){state.font=state.font==='large'?'normal':'large';save();render(true);}
 if(action==='section')document.getElementById(`section-${b.dataset.index}`)?.scrollIntoView({behavior:'smooth',block:'start'});
 if(action==='block')toggleBlock(b.dataset.id);
 if(action==='hours'){const v=Number(b.dataset.value);if(!studyHours.includes(v))return;state.todayHours={date:today(),hours:v};save();render(true);toast(`ปรับแผนวันนี้เป็น ${v} ชั่วโมงแล้ว`);}
 if(action==='prep-answer'){const code=b.dataset.course,g=prep[code],i=Number(b.dataset.index),v=Number(b.dataset.value);if(!g||!g.questions[i]||!Number.isInteger(v)||v<0||v>=g.questions[i].options.length)return;const p=state.prep[code]||(state.prep[code]={answers:{},submitted:false,best:null,last:null});if(prepMode==='exam'?p.submitted:Number.isInteger(p.answers[i]))return;p.answers[i]=v;if(prepMode==='practice'&&Object.keys(p.answers).length===g.questions.length){const r=prepResult(state,code);p.last=r.correct;p.best=Math.max(p.best??0,r.correct);toast(`ครบทุกข้อแล้ว ได้ ${r.correct}/${r.total} คะแนน`);}save();render(true);}
 if(action==='prep-submit'){const code=b.dataset.course,p=state.prep[code];if(!prep[code]||!p||p.submitted)return;p.submitted=true;const r=prepResult(state,code);p.last=r.correct;p.best=Math.max(p.best??0,r.correct);save();render(true);toast(`ได้ ${r.correct}/${r.total} คะแนน เลื่อนดูเฉลยแต่ละข้อได้เลย`);}
 if(action==='prep-reset'){const code=b.dataset.course;if(!prep[code])return;const p=state.prep[code];if(p&&Object.keys(p.answers).length&&!confirm('ล้างคำตอบชุดนี้แล้วเริ่มทำใหม่? คะแนนดีสุดยังเก็บไว้'))return;state.prep[code]={answers:{},submitted:false,best:p?.best??null,last:p?.last??null};save();render(true);document.getElementById('mock-title')?.scrollIntoView({block:'start'});}
 if(action==='prep-mode'){const code=b.dataset.course,mode=b.dataset.mode;if(!['practice','exam'].includes(mode)||mode===prepMode)return;const p=state.prep[code];if(p&&Object.keys(p.answers).length){if(!confirm('เปลี่ยนโหมดจะล้างคำตอบที่ทำค้างไว้ (คะแนนดีสุดยังเก็บไว้) ต้องการเปลี่ยนไหม?'))return;state.prep[code]={...p,answers:{},submitted:false};save();}prepMode=mode;render(true);}
 if(action==='answer'){const l=lessonById(b.dataset.lesson),i=Number(b.dataset.index),v=Number(b.dataset.value);if(!l||!l.questions[i]||v<0||v>=l.questions[i].options.length)return;state.answers[`${l.id}:${i}`]=v;save();if(reviewMode==='quiz'&&mistakesOnly&&currentView==='review'){toast(v===l.questions[i].answer?'ตอบถูกแล้ว นำออกจากข้อที่ต้องทบทวน':'บันทึกแล้ว ดูคำอธิบายเพื่อทบทวน');}render(true);}
 if(action==='retry'){for(const key of Object.keys(state.answers))if(key.startsWith(b.dataset.id+':'))delete state.answers[key];save();render(true);}
 if(action==='retry-one'){delete state.answers[b.dataset.id];save();render(true);}
 if(action==='complete'){const id=b.dataset.id;if(!lessonById(id))return;if(state.completed.includes(id)){state.completed=state.completed.filter(v=>v!==id);state.sessions=state.sessions.filter(v=>!(v.lesson===id&&v.date===today()));}else {state.completed.push(id);if(!state.sessions.some(v=>v.lesson===id&&v.date===today()))state.sessions.push({lesson:id,date:today()});}save();render(true);toast(state.completed.includes(id)?'บันทึกว่าอ่านจบแล้ว ✓ การ์ดของบทนี้เข้าคิวทบทวนแล้ว':'ยกเลิกเครื่องหมายแล้ว');}
 if(action==='mode'){reviewMode=b.dataset.mode;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(action==='flip'){flipped=!flipped;render(true);}
 if(action==='remember'){reviewCard(state,b.dataset.id,b.dataset.value==='yes');save();flipped=false;render(true);}
 if(action==='quiz-next'){quizIndex++;render(true);}
 if(action==='quiz-prev'){quizIndex=Math.max(0,quizIndex-1);render(true);}
 if(action==='calendar'){download('ru-exams-2-2569.ics',examICS(),'text/calendar;charset=utf-8');toast('ดาวน์โหลดปฏิทินแบบทั้งวันพร้อมรหัสคาบแล้ว');}
 if(action==='export')exportAll();
 if(action==='export-plan')exportPlan();
 if(action==='export-notes'){const text=lessons.filter(l=>state.notes[l.id]?.trim()).map(l=>`# ${l.course} — ${l.title}\n\n${state.notes[l.id]}`).join('\n\n---\n\n');download('ru-study-notes.md',text||'# ยังไม่มีบันทึก\n','text/markdown;charset=utf-8');}
 if(action==='save-transfer'){const general=Number(document.querySelector('#transfer-general').value),free=Number(document.querySelector('#transfer-free').value);if(!Number.isInteger(general)||general<0||general>30||!Number.isInteger(free)||free<0||free>12){toast('กรอกจำนวนเต็มตามช่วงที่ระบุ');return;}state.transfer={general,free};save();render(true);toast('บันทึกหน่วยกิตที่ยืนยันแล้ว');}
 if(action==='recover-session'&&confirm('ใช้ข้อมูลรอบนี้แทนข้อมูลเดิมที่อ่านไม่ได้? ควรส่งออกข้อมูลรอบนี้ก่อน')){locked=false;save();render(true);}
});
document.addEventListener('input',event=>{const el=event.target;if(!studySpace.info().canEdit&&el.id!=='lesson-search')return;if(el.id==='notebook-search'){notebookSearch(studySpace,el.value);return;}if(el.id==='lesson-search'){searchQuery=el.value;document.querySelector('#library-results').innerHTML=libraryResults();}if(el.id==='lesson-note'){state.notes[el.dataset.lesson]=el.value;const ok=save();document.querySelector('#note-status').textContent=ok?studySpace.info().status:'ยังไม่บันทึกใน Supabase กรุณาลองอีกครั้ง';}});
document.addEventListener('change',async event=>{const el=event.target;if(!studySpace.info().canEdit&&!['calendar-course','review-course','mistakes-only','include-unread'].includes(el.id))return;
 if(el.id==='notebook-course'){notebookFilter(el.value);render(true);return;}
 if(el.id==='notebook-import'){try{if(el.files?.[0]){await importNotebook(el.files[0],studySpace);render();}}catch(err){toast(err.message);}return;}
 if(el.id==='calendar-course'){calendarCourse(el.value);render(true);return;}
 if(el.id==='review-course'){reviewCourse=el.value;quizIndex=0;flipped=false;reviewQueue=null;render(true);}
 if(el.id==='mistakes-only'){mistakesOnly=el.checked;quizIndex=0;reviewQueue=null;render(true);}
 if(el.id==='include-unread'){includeUnread=el.checked;flipped=false;render(true);}
 if(el.classList.contains('grade-select')){if(el.value)state.grades[el.dataset.course]=el.value;else delete state.grades[el.dataset.course];save();render(true);toast('บันทึกผลที่กรอกแล้ว');}
 if(el.classList.contains('move-select')){state.termMoves[el.dataset.course]=Number(el.value);save();render(true);toast('ปรับภาคเรียนแล้ว ตรวจเพดานและวิชาเปิดก่อนลงจริง');}
 if(el.id==='hours-weekday'||el.id==='hours-weekend'){const v=Number(el.value);if(!studyHours.includes(v))return;state.hours[el.id==='hours-weekday'?'weekday':'weekend']=v;if(state.todayHours?.date===today())state.todayHours=null;save();render(true);toast('ปรับเวลาเรียนแล้ว แผนรายวันเปลี่ยนตาม');}
 if(el.id==='font-choice'){state.font=el.value;save();render(true);}
 if(el.id==='import-backup'){const file=el.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('ไฟล์เกิน 2 MB');const candidate=validateState(JSON.parse(await file.text()));if(!confirm(`นำเข้าบทที่อ่านจบ ${candidate.completed.length} บท และบันทึก ${Object.keys(candidate.notes).length} รายการ เพื่อแทนที่ข้อมูลบัญชีนี้และบันทึกเข้า Supabase?`)){el.value='';return;}state=candidate;locked=false;save();render();toast('นำเข้าข้อมูลสำเร็จ');}catch(err){toast('นำเข้าไม่สำเร็จ: '+(err.message||'รูปแบบไฟล์ไม่ถูกต้อง'));el.value='';}}
});
studySpace=createStudySpace({storage,progress:state,onProgress:value=>{state=validateState(value);locked=false;},onChange:()=>render(true),onStatus:info=>{
 if(typeof document.querySelectorAll==='function')document.querySelectorAll('[data-sync-status]').forEach(el=>el.textContent=info.status);
 const bar=document.getElementById('cloud-status-bar');if(bar){bar.dataset.phase=info.phase;bar.hidden=false;}
 for(const id of ['note-status','rich-note-status']){const el=document.getElementById(id);if(el)el.textContent=info.status;}
 storageWarning(info.cacheWarning);
 const google=document.getElementById('google-signin');if(google)google.disabled=!info.providers.google;
 const setup=document.getElementById('google-setup-note');if(setup)setup.hidden=!!info.providers.google;
 const conflict=document.getElementById('sync-conflict');if(conflict)conflict.hidden=!info.conflict;
 const last=document.getElementById('last-sync');if(last)last.textContent=info.lastSync?new Date(info.lastSync).toLocaleString('th-TH'):'ยังไม่มี';
}});
window.addEventListener('hashchange',navigate);
navigate();
export const appReady=studySpace.init();

